Recipe _r(String id, String name, String description, String category, String image,
    int prep, int cook, String difficulty, double rating, String cuisine,
    bool featured, List<String> ingredientNames, List<double> amounts) {
  final units = ['پیمانه', 'گرم', 'عدد', 'قاشق'];
  return Recipe(
    id: id, name: name, description: description, category: category,
    image: image, preparationMinutes: prep, cookingMinutes: cook,
    difficulty: difficulty, rating: rating, servings: 4, cuisine: cuisine,
    isFeatured: featured, calories: 280 + id.length * 21,
    ingredients: List.generate(ingredientNames.length, (i) => Ingredient(
      name: ingredientNames[i], amount: amounts[i], unit: units[i % units.length],
    )),
    steps: _cookingSteps(id, name),
  );
}

List<String> _cookingSteps(String id, String name) {
  switch (id) {
    case 'qabili': return ['برنج را بشویید و حدود نیم ساعت در آب نمک خیس کنید. گوشت را با پیاز، نمک و ادویه آرام بپزید.', 'زردک خلال‌شده را در کمی روغن تفت دهید؛ کشمش و چند دانه زیره را در پایان اضافه کنید.', 'برنج را در آب جوش نیم‌پز و آبکش کنید. آب گوشت را صاف کرده و برای دم‌کردن نگه دارید.', 'لایه‌های برنج و گوشت را در قابلمه بچینید، آب گوشت را بیفزایید و با حرارت کم دم کنید.', 'پلو را در دیس بکشید و با زردک، کشمش و گوشت روی آن تزئین کنید.'];
    case 'mantu': return ['آرد، آب و کمی نمک را ورز دهید تا خمیر یکدست شود؛ روی آن را بپوشانید و استراحت دهید.', 'گوشت چرخ‌کرده را با پیاز ریز، نمک و فلفل مخلوط کنید.', 'خمیر را نازک باز کرده، مربع ببرید و از مایهٔ گوشت در مرکز هر مربع بگذارید؛ گوشه‌ها را ببندید.', 'منتوها را در سبد بخارپز چرب‌شده بچینید و حدود سی دقیقه بخارپز کنید.', 'سس گوجه را جداگانه آماده کنید. منتو را با ماست سیر و نعنا و سس گرم سرو کنید.'];
    case 'ashak': return ['تره را ریز خرد کنید و با کمی نمک و فلفل نرم کنید؛ خمیر را نازک باز کرده و مربع ببرید.', 'مقداری تره در هر مربع بگذارید، لبه‌ها را با آب مرطوب کنید و محکم ببندید.', 'آشک‌ها را در آب نمک جوش بپزید تا خمیر نرم شود، سپس با کفگیر بیرون آورید.', 'عدس را با پیاز و گوجه بپزید تا سس غلیظی آماده شود.', 'آشک را با چکه یا ماست چکیده، سس عدس و نعنا سرو کنید.'];
    case 'bolani': return ['کچالو را آب‌پز و له کنید؛ ترهٔ خردشده، نمک، فلفل و کمی روغن را با آن مخلوط کنید.', 'خمیر را به گلوله‌های کوچک تقسیم و بسیار نازک باز کنید.', 'از مواد میانی روی نیمهٔ خمیر پخش کنید و نیمهٔ دیگر را روی آن برگردانید؛ لبه‌ها را ببندید.', 'بولانی را در تابهٔ داغ با روغن کم، هر طرف را تا طلایی و برشته شدن بپزید.', 'داغ و تازه، همراه ماست چکیده یا چتنی سبز میل کنید.'];
    case 'kachri': return ['ماش را بشویید و با آب بپزید تا نرم شود؛ برنج را جداگانه نیم‌پز کنید.', 'پیاز را طلایی کنید و زردچوبه را کوتاه تفت دهید تا عطر ادویه آزاد شود.', 'برنج و ماش را با کمی آب در قابلمه لایه کنید و روی حرارت ملایم دم بگذارید.', 'قروت را با آب گرم باز کنید و آرام هم بزنید تا سس یکدستی به دست آید.', 'کچری را با قروت گرم، پیاز داغ و نعنا سرو کنید.'];
    case 'shola': return ['گندم را از شب پیش خیس کنید؛ ماش را بشویید و آبکش نمایید.', 'گندم و ماش را با آب فراوان و کمی زردچوبه روی حرارت ملایم بگذارید.', 'هر از گاهی هم بزنید و در صورت نیاز آب داغ اضافه کنید تا دانه‌ها کاملاً نرم شوند.', 'پیاز را جداگانه طلایی کنید و بخشی از آن را با نمک به شوله بیفزایید.', 'وقتی غذا غلیظ و کشدار شد، با پیاز داغ و روغن گرم سرو کنید.'];
    case 'chalo-kebab': return ['گوشت را با پیاز رنده‌شدهٔ آب‌گرفته، نمک و ادویه ورز دهید و نیم ساعت استراحت دهید.', 'برنج را آبکش کنید و با کمی روغن و آب در قابلمه دم بگذارید.', 'گوشت را دور سیخ پهن کنید و روی منقل یا گریل داغ، مرتب بچرخانید تا برشته و آبدار بماند.', 'گوجه‌ها را کنار کباب کبابی کنید تا پوستشان کمی ترک بخورد.', 'کباب را با چلو، گوجهٔ داغ و سماق سرو کنید.'];
    case 'shorwa': return ['گوشت را با پیاز در کمی روغن تفت دهید تا رنگ آن تغییر کند.', 'نخود خیس‌خورده و آب گرم را اضافه کنید و بگذارید گوشت آرام نرم شود.', 'کچالو و هویج خردشده را به قابلمه بیفزایید و با در بسته بپزید.', 'نمک و ادویه را در نیمهٔ پایانی پخت تنظیم کنید تا سبزیجات شکل خود را حفظ کنند.', 'شوربا را داغ، با نان تازه و سبزی خوردن سرو کنید.'];
    case 'qorma-sabzi': return ['سبزی خورشتی را ریز خرد کنید و با حرارت متوسط تفت دهید تا عطر آن بلند شود.', 'گوشت و پیاز را در قابلمه جداگانه تفت دهید؛ لوبیا و زردچوبه را اضافه کنید.', 'سبزی سرخ‌شده، لیموعمانی سوراخ‌شده و آب جوش را به گوشت بیفزایید.', 'خورش را با حرارت بسیار کم بپزید تا گوشت نرم و خورش جاافتاده شود.', 'با برنج زعفرانی و پیاز تازه سرو کنید.'];
    case 'afghan-kebab': return ['گوشت را تکه کنید و با پیاز، ماست، زیره و کمی نمک مزه‌دار نمایید.', 'روی ظرف را بپوشانید و دست‌کم یک ساعت در یخچال استراحت دهید.', 'گوشت را به سیخ بکشید و فاصلهٔ تکه‌ها را یکسان نگه دارید.', 'روی زغال یا گریل متوسط بپزید و مرتب بچرخانید تا مغزپخت و آبدار بماند.', 'با نان گرم، پیاز و سبزی تازه به سفره بیاورید.'];
    case 'fesenjan': return ['گردوی آسیاب‌شده را روی حرارت کم چند دقیقه تفت دهید و آب سرد اضافه کنید.', 'مرغ را با پیاز جداگانه طلایی کنید و به قابلمهٔ گردو منتقل نمایید.', 'رب انار را بیفزایید و خورش را با شعلهٔ کم و در بسته آرام بپزید.', 'در طول پخت کمی آب سرد اضافه کنید تا گردو روغن بیندازد و سس غلیظ شود.', 'طعم ترش و شیرین را تنظیم کرده و با برنج سرو کنید.'];
    case 'pasta': return ['پاستا را در آب نمک‌دار جوش طبق زمان بسته بپزید و کمی از آب پخت را نگه دارید.', 'قارچ ورقه‌شده را با کمی روغن تفت دهید تا آب آن کشیده شود.', 'خامه را اضافه کنید و با حرارت کم، پنیر پارمزان و فلفل را در آن حل کنید.', 'پاستا را به سس بیفزایید و در صورت نیاز کمی آب پخت اضافه کنید.', 'با جعفری خردشده و پنیر تازه بلافاصله سرو نمایید.'];
    case 'pancakes': return ['آرد را با کمی نمک مخلوط کنید؛ شیر و تخم‌مرغ را جداگانه هم بزنید.', 'مواد مایع را به آرد اضافه کرده و فقط تا یکدست شدن مخلوط کنید.', 'تابهٔ نچسب را گرم و اندکی چرب کنید؛ برای هر پنکیک یک ملاقه مایه بریزید.', 'وقتی روی پنکیک حباب زد، آن را برگردانید و طرف دیگر را طلایی کنید.', 'با عسل و میوهٔ تازه، گرم و نرم سرو کنید.'];
